"""Grandfather-father-son snapshot retention. See task.md."""

from __future__ import annotations

import re
from datetime import datetime
from typing import NamedTuple


class RetentionError(ValueError):
    """Raised for an unusable policy or an unusable list of snapshots."""


class Kept(NamedTuple):
    snapshot: str
    reasons: tuple[str, ...]


_RULES = ("last", "hourly", "daily", "weekly", "monthly", "yearly")
_FORMAT = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})")


def _parse(snapshot: object) -> datetime:
    if not isinstance(snapshot, str):
        raise RetentionError(f"snapshot is not a string: {snapshot!r}")
    m = _FORMAT.fullmatch(snapshot)
    if m is None:
        raise RetentionError(f"malformed snapshot: {snapshot!r}")
    try:
        return datetime(*map(int, m.groups()))
    except ValueError:
        raise RetentionError(f"nonexistent date or time: {snapshot!r}") from None


def _bucket(rule: str, dt: datetime) -> tuple:
    if rule == "hourly":
        return (dt.year, dt.month, dt.day, dt.hour)
    if rule == "daily":
        return (dt.year, dt.month, dt.day)
    if rule == "weekly":
        return dt.isocalendar()[:2]
    if rule == "monthly":
        return (dt.year, dt.month)
    return (dt.year,)


def retain(snapshots: list[str], policy: dict) -> list[Kept]:
    """Return the snapshots `policy` keeps, newest first, with the rules that keep each."""
    if not isinstance(policy, dict):
        raise RetentionError("policy must be a dict")
    for key, n in policy.items():
        if key not in _RULES:
            raise RetentionError(f"unknown rule: {key!r}")
        if type(n) is not int or n < 0:
            raise RetentionError(f"invalid count for {key!r}: {n!r}")
    if not any(n > 0 for n in policy.values()):
        raise RetentionError("policy keeps nothing")

    parsed = [(_parse(s), s) for s in snapshots]
    if len({s for _, s in parsed}) != len(parsed):
        raise RetentionError("duplicate snapshot")
    parsed.sort(key=lambda p: p[0], reverse=True)

    reasons: dict[str, list[str]] = {}
    for rule in _RULES:
        n = policy.get(rule, 0)
        if n == 0:
            continue
        if rule == "last":
            chosen = [s for _, s in parsed[:n]]
        else:
            seen: set = set()
            chosen = []
            for dt, s in parsed:
                b = _bucket(rule, dt)
                if b in seen:
                    continue
                if len(seen) == n:
                    break
                seen.add(b)
                chosen.append(s)
        for s in chosen:
            reasons.setdefault(s, []).append(rule)

    return [Kept(s, tuple(reasons[s])) for _, s in parsed if s in reasons]
